import React from 'react';
import PropTypes from 'prop-types';
import { MdClose } from 'react-icons/md';
import PanelGuides from './panel-guides';
import PanelLayers from './panel-layers';
import PanelLayerElements from './panel-layer-elements';
import PanelGroups from './panel-groups';
import PanelElementEditor from './panel-element-editor/panel-element-editor';
import PanelGroupEditor from './panel-group-editor';
import * as SharedStyle from '../../shared-style';

const backdropStyle = {
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
    zIndex: 100,
    opacity: 0,
    visibility: 'hidden',
    transition: 'opacity 0.3s ease, visibility 0.3s ease'
};

const backdropOpenStyle = {
    ...backdropStyle,
    opacity: 1,
    visibility: 'visible'
};

const drawerStyle = {
    position: 'fixed',
    top: 0,
    right: 0,
    backgroundColor: SharedStyle.PRIMARY_COLOR.main,
    overflowY: 'auto',
    overflowX: 'hidden',
    zIndex: 101,
    transform: 'translateX(100%)',
    transition: 'transform 0.3s ease',
    boxShadow: '-4px 0 20px rgba(0, 0, 0, 0.3)'
};

const drawerOpenStyle = {
    transform: 'translateX(0)'
};

const headerStyle = {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '16px',
    borderBottom: `1px solid ${SharedStyle.PRIMARY_COLOR.alt}`,
    backgroundColor: SharedStyle.PRIMARY_COLOR.alt
};

const titleStyle = {
    color: '#fff',
    fontSize: '16px',
    fontWeight: '600',
    margin: 0
};

const closeButtonStyle = {
    backgroundColor: 'transparent',
    border: 'none',
    color: '#fff',
    cursor: 'pointer',
    padding: '8px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: '50%',
    transition: 'background-color 0.2s ease',
    minWidth: '44px',
    minHeight: '44px'
};

const contentStyle = {
    paddingBottom: '80px' // Extra space for mobile toolbar
};

export default function SidebarDrawer({ isOpen, onClose, width, height, state, sidebarComponents }, context) {
    const { translator } = context;

    const selectedLayer = state.getIn(['scene', 'selectedLayer']);
    const selected = state.getIn(['scene', 'layers', selectedLayer, 'selected']);

    const multiselected =
        selected.lines.size > 1 ||
        selected.items.size > 1 ||
        selected.holes.size > 1 ||
        selected.areas.size > 1 ||
        selected.lines.size + selected.items.size + selected.holes.size + selected.areas.size > 1;

    const selectedGroup = state.getIn(['scene', 'groups']).findEntry(g => g.get('selected'));

    // Handle backdrop click
    const handleBackdropClick = (e) => {
        if (e.target === e.currentTarget) {
            onClose();
        }
    };

    // Handle touch swipe to close
    let touchStartX = 0;
    const handleTouchStart = (e) => {
        touchStartX = e.touches[0].clientX;
    };

    const handleTouchEnd = (e) => {
        const touchEndX = e.changedTouches[0].clientX;
        const swipeDistance = touchEndX - touchStartX;
        // If swiped right more than 50px, close the drawer
        if (swipeDistance > 50) {
            onClose();
        }
    };

    return (
        <React.Fragment>
            {/* Backdrop */}
            <div
                style={isOpen ? backdropOpenStyle : backdropStyle}
                onClick={handleBackdropClick}
                aria-hidden={!isOpen}
            />

            {/* Drawer */}
            <aside
                style={{
                    ...drawerStyle,
                    width,
                    height,
                    ...(isOpen ? drawerOpenStyle : {})
                }}
                onTouchStart={handleTouchStart}
                onTouchEnd={handleTouchEnd}
                className="sidebar-drawer"
                aria-hidden={!isOpen}
            >
                {/* Header */}
                <div style={headerStyle}>
                    <h2 style={titleStyle}>{translator.t('Panneau de contrôle')}</h2>
                    <button
                        style={closeButtonStyle}
                        onClick={onClose}
                        aria-label={translator.t('Fermer')}
                    >
                        <MdClose size={24} />
                    </button>
                </div>

                {/* Panels */}
                <div
                    style={contentStyle}
                    onKeyDown={event => event.stopPropagation()}
                    onKeyUp={event => event.stopPropagation()}
                >
                    <PanelGuides state={state} />
                    <PanelLayers state={state} />
                    <PanelLayerElements
                        mode={state.mode}
                        layers={state.scene.layers}
                        selectedLayer={state.scene.selectedLayer}
                    />
                    <PanelGroups
                        mode={state.mode}
                        groups={state.scene.groups}
                        layers={state.scene.layers}
                    />
                    {!multiselected && <PanelElementEditor state={state} />}
                    {!!selectedGroup && (
                        <PanelGroupEditor
                            state={state}
                            groupID={selectedGroup ? selectedGroup[0] : null}
                        />
                    )}

                    {/* Additional sidebar components */}
                    {sidebarComponents && sidebarComponents.map((Component, key) => {
                        return Component.prototype ?
                            React.createElement(Component, { state, key }) :
                            React.createElement(Component.dom, { state, key });
                    })}
                </div>
            </aside>
        </React.Fragment>
    );
}

SidebarDrawer.propTypes = {
    isOpen: PropTypes.bool.isRequired,
    onClose: PropTypes.func.isRequired,
    width: PropTypes.number.isRequired,
    height: PropTypes.number.isRequired,
    state: PropTypes.object.isRequired,
    sidebarComponents: PropTypes.array
};

SidebarDrawer.contextTypes = {
    translator: PropTypes.object.isRequired
};

SidebarDrawer.defaultProps = {
    sidebarComponents: []
};
